android.extraProguardRules:
# Google Play Services (Google Sign-In + Mobile Ads)
-dontwarn com.google.android.gms.**
-keep class com.google.android.gms.auth.api.signin.** { *; }
-keep class com.google.android.gms.common.internal.** { *; }
-keep class com.google.android.gms.tasks.** { *; }
-keep class com.google.android.gms.ads.** { *; }
-keep class com.google.android.gms.ads.initialization.** { *; }
# React Native
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-keep class com.facebook.react.modules.** { *; }
-keep class com.facebook.react.runtime.** { *; }
-dontwarn com.facebook.react.**
-dontwarn com.facebook.yoga.**
# Expo modules
-keep class expo.modules.** { *; }
-dontwarn expo.modules.**
# react-native-reanimated
-keep class com.swmansion.reanimated.** { *; }
# react-native-gesture-handler
-keep class com.swmansion.gesture_handler.** { *; }
# Skia
-keep class com.shopify.reactnative.skia.** { *; }
# Safe area context
-keep class com.th3rdwave.safeareacontext.** { *; }
# Screens
-keep class com.th3rdwave.screens.** { *; }
# Keep annotations and signatures
-keepattributes Signature, *Annotation*, InnerClasses, EnclosingMethod
